input.command:
cd /tmp && cat > mcp-measure.mjs <<'EOF'
import { spawn } from 'node:child_process';

const ROUGH_TOKENS_PER_CHAR = 1/3.6;

async function listTools(server) {
  const requests = [
    { jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'measure', version: '0' } } },
    { jsonrpc: '2.0', method: 'notifications/initialized' },
    { jsonrpc: '2.0', id: 2, method: 'tools/list' },
  ];
  const cmd = server.cmd[0];
  const args = server.cmd.slice(1);
  return new Promise((res, rej) => {
    const child = spawn(cmd, args, { stdio: ['pipe', 'pipe', 'pipe'] });
    let buf = '';
    const out = [];
    child.stdout.on('data', d => {
      buf += d.toString();
      let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i); buf = buf.slice(i+1);
        if (!line.trim()) continue;
        try {
          const msg = JSON.parse(line);
          if (msg.id === 2) { out.push(msg); child.kill(); res(msg); }
        } catch {}
      }
    });
    child.stderr.on('data', () => {});
    child.on('error', rej);
    setTimeout(() => { child.kill(); res(out[0] || null); }, 8000);
    for (const r of requests) child.stdin.write(JSON.stringify(r) + '\n');
  });
}

async function listToolsHttp(url) {
  // try MCP HTTP transport: POST initialize + tools/list
  const init = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'measure', version: '0' } } }),
  });
  const sid = init.headers.get('mcp-session-id');
  const headers = { 'content-type': 'application/json', accept: 'application/json, text/event-stream' };
  if (sid) headers['mcp-session-id'] = sid;
  await fetch(url, { method: 'POST', headers, body: JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) });
  const r = await fetch(url, {
    method: 'POST', headers,
    body: JSON.stringify({ jsonrpc: '2.0', id: 2, method: 'tools/list' }),
  });
  const ct = r.headers.get('content-type') || '';
  const text = await r.text();
  if (ct.includes('event-stream')) {
    for (const line of text.split('\n')) {
      if (line.startsWith('data: ')) {
        try { const msg = JSON.parse(line.slice(6)); if (msg.id === 2) return msg; } catch {}
      }
    }
    return null;
  }
  return JSON.parse(text);
}

const servers = [
  { name: 'context7', http: 'https://mcp.context7.com/mcp' },
  { name: 'openaiDeveloperDocs', http: 'https://developers.openai.com/mcp' },
  { name: 'chrome-devtools', cmd: ['npx', '-y', 'chrome-devtools-mcp@latest'] },
  { name: 'oracle', cmd: ['oracle-mcp'] },
  { name: 'flux-operator-mcp', cmd: ['flux-operator-mcp-claude'] },
];

const rows = [];
for (const s of servers) {
  try {
    const resp = s.http ? await listToolsHttp(s.http) : await listTools({ cmd: s.cmd });
    const tools = resp?.result?.tools || [];
    const json = JSON.stringify(tools);
    const chars = json.length;
    const tokensApprox = Math.round(chars * ROUGH_TOKENS_PER_CHAR);
    rows.push({ server: s.name, tools: tools.length, chars, tokensApprox });
  } catch (e) {
    rows.push({ server: s.name, error: String(e).slice(0,80) });
  }
}

const total = rows.reduce((a, r) => a + (r.tokensApprox || 0), 0);
console.log(JSON.stringify({ rows, totalApprox: total }, null, 2));
EOF
node mcp-measure.mjs 2>&1

